(() => {
  const css=document.createElement('style');css.textContent=`
  .week-pro{max-width:960px;margin:auto}.week-hero{padding:28px;border-radius:24px;background:linear-gradient(120deg,#082e55,#15598d);color:#fff;box-shadow:var(--shadow)}.week-hero h2{margin:7px 0}.week-hero p{margin:0;color:#d9eaff;line-height:1.65}.week-chip{display:inline-block;padding:5px 10px;border-radius:99px;background:#ffd567;color:#654400;font-size:.8rem;font-weight:800}.week-road{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:18px 0}.road{padding:12px;border-radius:13px;background:#fff;border:1px solid var(--line);color:#496983;font-size:.88rem}.road b{display:block;color:#113b61}.road.active{background:#eef7ff;border-color:#7cb9e8}.road.done{background:#e7f7ed;border-color:#9fd7b3}.week-paper{margin-top:18px;background:#fff;border-radius:22px;padding:25px;box-shadow:var(--shadow)}.week-paper h3{margin:0;color:var(--navy)}.week-question{padding:18px 0;border-top:1px solid var(--line)}.week-question:first-of-type{border-top:0}.week-question b{color:#123d63}.week-question p{line-height:1.65}.choice-stack{display:grid;gap:8px;margin-top:10px}.choice-stack label{padding:11px 12px;border:1px solid #d2e0ed;border-radius:10px;cursor:pointer;line-height:1.55}.choice-stack label:has(input:checked){border-color:#247bb5;background:#edf8ff}.week-paper input{box-sizing:border-box;width:100%;padding:11px;border:1px solid var(--line);border-radius:10px;font:inherit}.week-result{display:none;margin-top:16px;padding:15px;border-radius:13px;line-height:1.7}.week-result.show{display:block}.week-result.good{background:#e7f7ed;color:#205d43}.week-result.bad{background:#fff4ee;color:#8b4837}.week-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.review-kpi{padding:17px;border-radius:15px;background:#fff;border:1px solid var(--line)}.review-kpi span{display:block;color:var(--muted);font-size:.84rem}.review-kpi b{display:block;font-size:1.7rem;color:var(--navy);margin:4px 0}.next-list{display:grid;gap:9px;margin-top:14px}.next-item{padding:13px 14px;border-left:4px solid #f0ae25;background:#fffaf0;border-radius:0 11px 11px 0;color:#5e4818;line-height:1.6}.true-toggle{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.true-toggle button{padding:10px 13px;border:1px solid #c9d9e7;border-radius:10px;background:#fff;color:#143c61;font:inherit;cursor:pointer}.true-toggle button.active{background:#123d63;border-color:#123d63;color:#fff}.audit-card{padding:16px;margin-top:10px;border:1px solid var(--line);border-radius:14px;background:#fff}.audit-card b{color:var(--navy)}.audit-card small{display:block;color:var(--muted);line-height:1.55;margin-top:6px}.lock{padding:22px;border-radius:16px;background:#fff7df;border:1px solid #f0db8e;color:#674c0a;line-height:1.7}.source-link{color:#1d6fa8;text-decoration:underline}@media(max-width:720px){.week-road,.review-grid{grid-template-columns:1fr 1fr}.week-paper{padding:20px}}`;
  document.head.appendChild(css);
  const K='ci-jing-weekend-v2',read=()=>{try{return {...{done:false,score:0,wrong:[],reflection:''},...JSON.parse(localStorage.getItem(K))}}catch{return{done:false,score:0,wrong:[],reflection:''}}},write=x=>localStorage.setItem(K,JSON.stringify(x));
  const sat=document.getElementById('saturday'),sun=document.getElementById('sunday'),exam=document.getElementById('exam'); if(!sat||!sun||!exam)return;
  sat.innerHTML=`<div class="week-pro"><span id="saturdayStatus" style="display:none"></span><div class="week-hero"><span class="week-chip">周六 · 18 分钟</span><h2>本周能力验证</h2><p>用陌生语境检验这周会不会用。它只测试本周学过的词汇、搭配、语法与证据判断；全部作答后统一批改。</p></div><div class="week-road"><div class="road active"><b>01 词义</b>语境辨义</div><div class="road"><b>02 搭配</b>结构补全</div><div class="road"><b>03 语法</b>关系判断</div><div class="road"><b>04 阅读</b>证据边界</div></div><section class="week-paper"><h3>开始本周验证</h3><p class="smallnote">编辑练习，不标为上海高考正式真题。请勿回看本周课程。</p><div class="week-question"><b>1 · 词义迁移</b><p class="en">The committee changed the plan to <strong>reflect</strong> students’ suggestions.</p><p>reflect 在这句中最接近：</p><div class="choice-stack"><label><input type="radio" name="q1" value="a"> 反射光线</label><label><input type="radio" name="q1" value="b"> 反映、体现</label><label><input type="radio" name="q1" value="c"> 再次考虑</label></div></div><div class="week-question"><b>2 · 搭配重建</b><p class="en">The library provides new readers ___ a digital guide.</p><input id="wq2" placeholder="填入一个英文词"></div><div class="week-question"><b>3 · 语法关系</b><p>选出正确句子：</p><div class="choice-stack"><label><input type="radio" name="q3" value="a"> Although the number rose, but the claim was not proved.</label><label><input type="radio" name="q3" value="b"> Although the number rose, the claim was not proved.</label><label><input type="radio" name="q3" value="c"> Although rose the number, the claim was not proved.</label></div></div><div class="week-question"><b>4 · 阅读证据边界</b><div class="material">A school offered a quiet reading room after class. More students visited it and several said they could focus better. The school did not compare their reading scores with those of students who did not use the room.</div><p>最稳妥的结论是：</p><div class="choice-stack"><label><input type="radio" name="q4" value="a"> 阅读室一定提高了所有学生的成绩。</label><label><input type="radio" name="q4" value="b"> 阅读室可能改善了学习环境，但材料不能证明它提高了成绩。</label><label><input type="radio" name="q4" value="c"> 没有使用阅读室的学生成绩一定更差。</label></div></div><div class="week-actions"><button class="primary" id="gradeWeekend">提交并批改</button><button class="secondary" id="resetWeekendV2">重做本次验证</button></div><div class="week-result" id="weekResult"></div></section></div>`;
  sun.innerHTML=`<div class="week-pro"><div style="display:none"><span id="weeklyAnswers"></span><span id="reviewDue"></span><span id="saturdayDone"></span><div id="reviewList"></div></div><div class="week-hero"><span class="week-chip">周日 · 12 分钟</span><h2>复盘不是重做，而是决定下周先练什么。</h2><p>只看本周验证与词汇标记的信号，把“我觉得不熟”变成下周可执行的复习顺序。</p></div><div id="sundayBody"></div></div>`;
  function grade(){const answers=[document.querySelector('input[name=q1]:checked')?.value==='b',document.getElementById('wq2').value.trim().toLowerCase()==='with',document.querySelector('input[name=q3]:checked')?.value==='b',document.querySelector('input[name=q4]:checked')?.value==='b'];if(answers.some(x=>x===false)&&(!document.querySelector('input[name=q1]:checked')||!document.getElementById('wq2').value.trim()||!document.querySelector('input[name=q3]:checked')||!document.querySelector('input[name=q4]:checked'))){document.getElementById('weekResult').className='week-result show bad';document.getElementById('weekResult').textContent='请完成 4 题后再提交。空答案不会计分。';return}const wrong=answers.map((x,i)=>x?null:i).filter(x=>x!==null),score=4-wrong.length,st={done:true,score,wrong,at:new Date().toISOString()};write(st);const notes=['词义：reflect = 反映、体现。','搭配：provide sb with sth。','although 后不能再用 but。','材料没有比较成绩，因此只能说学习环境可能改善。'];const box=document.getElementById('weekResult');box.className='week-result show '+(score===4?'good':'bad');box.innerHTML='<b>'+score+' / 4 项正确</b><br>'+answers.map((x,i)=>(i+1)+'. '+(x?'正确':'待巩固：'+notes[i])).join('<br>')+'<br><br>'+(score===4?'本周验证通过。周日可做一次短复盘。':'周日将把待巩固项排为下周优先复习。');renderSunday()}
  document.getElementById('gradeWeekend').onclick=grade;document.getElementById('resetWeekendV2').onclick=()=>{write({done:false,score:0,wrong:[],reflection:''});document.querySelectorAll('input').forEach(x=>x.checked=false);document.getElementById('wq2').value='';document.getElementById('weekResult').className='week-result';renderSunday()};
  function renderSunday(){const s=read(),labels=['词义与语境','固定搭配','语法让步结构','阅读证据边界'],weak=s.wrong?.map(x=>labels[x])||[];document.getElementById('sundayBody').innerHTML=`<div class="review-grid"><div class="review-kpi"><span>周六得分</span><b>${s.done?s.score+'/4':'未完成'}</b><span>陌生语境验证</span></div><div class="review-kpi"><span>下周优先项</span><b>${weak.length||'—'}</b><span>${weak.length?'从弱项开始':'完成验证后生成'}</span></div><div class="review-kpi"><span>词汇复习</span><b>6</b><span>第 1 天先回忆</span></div></div><section class="week-paper"><h3>下周第一天的复习顺序</h3>${s.done?(weak.length?`<div class="next-list">${weak.map((x,n)=>`<div class="next-item"><b>${n+1}. ${x}</b><br>先做 2 分钟闭卷回忆，再回看本周对应词卡或篇章解释。</div>`).join('')}</div>`:'<div class="next-item"><b>本周验证通过</b><br>下周先进行 6 个词汇的间隔回忆，再做新的篇章训练。</div>'):'<div class="next-item"><b>尚未生成</b><br>请先完成周六的 4 项验证，系统才会给出下周优先项。</div>'}<div class="week-question"><b>一句话复盘</b><p>哪一个环节最容易让你犹豫？写下原因，帮助下周判断是词义、搭配、语法还是篇章问题。</p><textarea id="weeklyReflection" class="weekend-answer" placeholder="例如：我知道 reflect 的中文，但放进句子里会和 response 混淆。">${s.reflection||''}</textarea></div><div class="week-actions"><button class="primary" id="saveReflection">保存复盘并进入下周</button><button class="secondary" id="toStudy">回到每日学习</button></div><div class="week-result" id="reflectDone"></div></section>`;document.getElementById('saveReflection').onclick=()=>{const x=read();x.reflection=document.getElementById('weeklyReflection').value.trim();write(x);const b=document.getElementById('reflectDone');b.className='week-result show good';b.textContent='复盘已保存。下周从词汇回忆和本周待巩固项开始。'};document.getElementById('toStudy').onclick=()=>document.querySelector('[data-view=study]').click()}
  function examView(mode='strict'){const rows=[['2025 年 6 月 · 秋季','候选多源转录','公开转载页存在，尚未完成逐题核验','https://www.shmeea.edu.cn/page/02200/20250609/19465.html'],['2024 年 1 月 · 外语一考','候选部分转录','卷面完整性与题号连续性未确认','https://www.shmeea.edu.cn/page/02300/20240107/18127.html'],['2022 年 7 月 · 秋季','候选部分转录','实际月份已校正，但原卷与答案来源仍待交叉核验','https://www.shmeea.edu.cn/page/02200/20220708/16505.html']];exam.innerHTML=`<div class="week-pro"><div class="week-hero"><span class="week-chip">上海高考英语 · 题库审计</span><h2>真题测试必须先过来源核验。</h2><p>当前不能把候选卷的题目按“上海高考真题”投放。选择模式前，请看清它对学习结果的影响。</p></div><div class="true-toggle"><button id="strictMode" class="${mode==='strict'?'active':''}">仅正式真题 · 严格模式</button><button id="candidateMode" class="${mode==='candidate'?'active':''}">候选资料审阅 · 不计真题成绩</button></div><section class="week-paper" id="examBody"></section></div>`;const body=document.getElementById('examBody');body.innerHTML=mode==='strict'?`<div class="lock"><b>正式真题：0 题</b><br>此模式只接受已保存完整卷面、逐题核验来源和答案来源的材料。当前没有合格记录，因此不提供所谓“真题测试”。<br><br>你可选择下方的“候选资料审阅”查看研究进度；它不会进入个人真题正确率，也不会显示为正式题。</div>`:`<div class="lock"><b>候选资料审阅模式</b><br>它用于透明查看本地资料的核验缺口，帮助决定后续哪些卷可以人工复核；不是正式测试，不能用于判断上海真题得分。</div>${rows.map(x=>`<article class="audit-card"><b>${x[0]}</b><small>状态：${x[1]}<br>${x[2]}<br><a class="source-link" href="${x[3]}" target="_blank" rel="noreferrer">查看上海市教育考试院对应官方评析</a></small></article>`).join('')}`;document.getElementById('strictMode').onclick=()=>examView('strict');document.getElementById('candidateMode').onclick=()=>examView('candidate')}
  renderSunday();examView();
})();
